import test from "node:test";
import assert from "node:assert/strict";
import { checkout } from "../src/checkout.mjs";

test("checkout includes phone field", () => {
  const items = [{ id: "1", price: 100, quantity: 2 }];
  const customer = {
    id: "c1",
    name: "Santino",
    email: "santino@example.com",
    phone: "555-1234"
  };

  const result = checkout(items, customer);

  assert.equal(result.customer.phone, "555-1234");
  assert.equal(result.customer.name, "Santino");
  assert.equal(result.customer.email, "santino@example.com");
  assert.equal(result.subtotal, 200);
  assert.equal(result.total, 200);
});

